#!/usr/bin/env python3
# reserve_L13f.py — 새 과 L13f(깃발 다섯 연대의 출정 · 세계 s13 의 f) — 면역 세계 「성 방어전」의 여섯째 장(항체 구조 · IgG · IgM · IgA · IgE · IgD · 중화 · 옵소닌화 · 보체).
#  L13c 부터의 방식 — 「L13e 에서 불어난 벌들이 둥근 탑에서 다섯 연대로 나뉘어 출정한 날」 한 장면(Gemini 가 통째로 그림 + 구역 편집 + PIL).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']; G = d['_글자모양사전']
B = '[2026-11-15 새 과 L13f]'
new = {
 'Y 자 황토 깃발 — 두 팔 끝의 집게 · 깃발 천 + 곧은 깃대(성 세계의 항체 꼴)': f'항체 한 분자의 꼴(가변부위 = 팔 끝 · N 말단 · 항원결합 / 불변부위 = 곧은 깃대 · C 말단 · 종류와 효과기능) 전용 {B} — L13f 전체. L13a ~ e 의 황토빛 깃발을 가까이서 본 꼴 · 【하늘색 Y자 집게】(L46c · L53a 의 면역글로불린)와 같은 Y — 세계마다 물건 하나. 깃발 천 = V(L13e). ⚠ 작은 Y 를 곧은 선으로만 그리면 독자 셋이 「곧은 쪽이 몸에 붙었다」로 거꾸로 읽었다(일치 검사 1 · 2회 · 따로 본 시험 셋) → 팔 끝이 안으로 굽은 「집게 Y」(`L13f_ylib.claw_y`)로 바꾸자 바로 읽혔다 · 집게 곁의 작은 세모 천은 「가시」로 읽혀 뺐다. ⚠ Gemini 는 「갈래 끝으로 붙고 깃대가 바깥」을 두 번 다 거꾸로(깃대를 꽂은 핀) 그렸다 — 작은 Y 는 PIL.',
 '큰 Y 깃발을 넷이 듦 — 아래 큰 벌 둘의 긴 장대(줄기에서 갈라져 두 팔로) · 위쪽 날개 단 작은 벌 둘의 짧은 장대(두 팔에 밧줄로)': f'항체 = 중쇄(H) 2 + 경쇄(L) 2 · 이황화 결합(밧줄) 전용 {B} — L13f s1 · s2(팔 끝 집게가 세균 머리의 별 돌기를 묾 · 깃발 천의 별 = 그 항원결정부위에만 맞음 · 팔 하나에 세균 하나 = 결합 자리 둘). 큰 벌 = 무거운(중) · 작은 벌 = 가벼운(경). ⚠ 처음 바탕은 오른쪽 작은 벌이 묶이지 않은 막대를 하나 더 쥐고 오른쪽 세균이 별 막대를 쥐어(일치 검사 1회) 같은 채팅 덧붙임 ZA3 로 팔 끝에 집게를 달며 지웠다.',
 'D 자 흰 명찰(곧은 왼쪽 · 둥근 오른쪽 · 빈칸)을 달고 탑 벽에 기대 하품하는 벌': f'IgD — 성숙 B 세포 겉의 수용체 · 하는 일(효과기능)이 뚜렷하지 않음 전용 {B} — L13f s3(옛 s13p01#4 「D자 명찰만 달고 아무것도 안 함」). D = 【_글자모양사전】 D. ⚠ Gemini 의 명찰은 모서리 둥근 네모로 읽혀(일치 검사 1회) PIL 로 다시 그렸다.',
 '지팡이 손잡이 Y 깃발의 가장 큰 무리 + Y 깃발이 꽉 찬 진홍 호스의 둥근 유리창 셋': f'IgG — 혈청에 가장 많음 · 단량체 전용 {B} — L13f s4(옛 s13p01#1). 지팡이 = G(【지팡이】 「지」) · 진홍 호스 = 혈관(L13b). ⚠ Gemini 는 지팡이 깃발을 잿빛 나무색으로 그려 「같은 Y 인데 빛깔이 다르다」(일치 검사 4회) → PIL 로 황토. ⚠ 호스 창을 처음엔 받침대 위 둥근 창(호스 밖)으로 그려 구역 편집 ZB 로 호스 몸에.',
 '유리 공처럼 비치는 임신부(연두 원피스)의 배 — 벌이 밀어 넣은 지팡이 깃발을 유리가 물결치며 통과시키고 웅크린 아기가 받음': f'IgG 만 태반 통과 → 자연 수동면역(기억 없음) 전용 {B} — L13f s5. 유리 = 태반. ⚠ 【분홍 천막(엄마 배) 속 아기 집】(태아 순환 · L46h)과 가른다 — 이쪽은 유리 공 배 · 깃발. 여자 옷은 빨강 금지(붉은 배지가 묻힌다 · L13b).',
 '뚱보 경비 배 왼쪽에 거꾸로 박힌 집게 Y 셋(곧은 깃대가 배에) + 위의 두 집게가 함께 문 노란 가시 꽃가루 공 → 확 타오른 성냥': f'IgE — 불변부위(Fc)로 비만세포에 붙어 있다가 알레르겐이 둘을 이으면(교차결합) 히스타민 방출 · 히스타민은 비만세포의 매개물질이지 항체(IgG) 기능이 아님 전용 {B} — L13f s6(옛 s13p01#3). 뚱보 경비 = 비만세포(L13b) · 성냥 = 【불붙은 성냥】. 깃대 끝은 배 윤곽이 덮게(박힘) PIL. ⚠ Gemini 의 배 위 깃발은 방향이 섞여 읽혀(일치 검사 2회) 같은 채팅 ZE2c 로 지우고 PIL. 꽃가루 = 가시 돋친 노란 공(알갱이 점).',
 '세 갈래 갈퀴로 성벽 틈의 분홍 벌레(기생충)를 미는 벌': f'IgE — 기생충(연충) 방어 전용 {B} — L13f s7(옛 s13p01#3). 세 갈래 = E(【_글자모양사전】). ⚠ 【네 갈퀴 포크】(포르밀) — 처음 바탕은 네 갈퀴라 ZE1 · ZE1b 로 셋. ⚠ 【애벌레 갑옷 …】 · 【… 지렁이 꼴 붉은 흙 광】과 가른다 — 이쪽은 성벽 틈의 분홍 벌레.',
 'Y 다섯을 깃대 밑동끼리 이은 별 바퀴(나무 바퀴 둘 위) + 가운데 두 봉우리 검은 쇠 장식 + 위쪽 끝에 몰린 성난 세균 셋': f'IgM — 5량체(결합 자리 10) · 응집 · 1차 반응에 먼저 · 태반 못 지남 전용 {B} — L13f s8(옛 s13p01#0). 두 봉우리 = M(【_글자모양사전】 — 처음 바탕은 원판에 글자 M 을 써서 ZF 로 쇠 장식). ⚠ 왕관으로 그리지 않는다(【금빛 왕관】 코로나).',
 '별 바퀴에 밀려 비스듬히 밀려난 저수지 판자(보) + 바퀴 끝 세균 배 구멍의 물줄기': f'보체 고전경로 — 항체(IgM 이 가장 잘 · IgG 도)가 켬 → 막공격복합체(용해) 전용 {B} — L13f s9. 저수지 물 = 보체(L13a · L13b 의 보) · 구멍 = 【몸 가운데 둥근 구멍 …】(MAC). ⚠ 물줄기의 방향(구멍으로 드는가 · 나오는가)은 그림만으로 애매 — 글은 「구멍으로 물이 쏟아져 나온다」. 판자는 「막던 보」보다 「얹힌 널빤지」로 읽힌다(3 ~ 5회).',
 'A 자 접이 사다리 위 쌍둥이 벌의 이음 깃발(Y 둘을 깃대 끝끼리 J 자 쇠고리로) + 우는 아이의 큰 눈물방울 · 샘물 속 작은 이음 깃발': f'IgA — 눈물 · 침 · 모유 · 점막 분비물 · 분비형 이량체(J 사슬) · 혈액에선 단량체 전용 {B} — L13f s10(옛 s13p01#2). A 자 사다리 = A · J 자 고리 = J(【_글자모양사전】). 작은 이음 깃발은 PIL(`double_y`). ⚠ 【두 팔을 위로 벌려 몸이 Y 자가 된 쌍둥이 둘】(PYY)과 가른다 — 이쪽은 쌍둥이 벌이 Y 깃발을 든다.',
 '두 손을 작은 집게 Y 들이 빼곡히 물어 창틀을 못 잡고 어두운 창 안쪽만 짚는 보라 망토(흰 두루마리를 등에)': f'중화 — 항체가 병원체 겉의 붙는 자리를 덮어 세포 부착 · 침입을 막음(독소도) 전용 {B} — L13f s11. 망토 = 바이러스 · 오두막 = 세포. ⚠ Gemini 는 손에 깃발을 거꾸로(깃대 쪽을) 붙여 ZJ2 로 지우고 PIL 집게.',
 '집게 Y 투성이 세균을 두 손으로 붙들어 삼키는 큰 흰 덩이(손 밑으로 깃대가 들어감)': f'옵소닌화 — 항체가 표지한 병원체를 식세포가 Fc 로 잡아 더 잘 먹음 전용 {B} — L13f s12. 흰 덩이 = 대식세포(L13a). 덩이의 손은 PIL 로 깃대 위에 다시 덮었다(깃대를 쥠).',
 '집게 Y 투성이(깃대가 바깥으로)인데 다친 데 없이 신나서 춤추는 세균': f'항체는 병원체를 직접 죽이지 않는다 — 표지 · 중화 · 옵소닌화 · 보체로 돕는다 전용 {B} — L13f s13. ⚠ 【혀를 쏙 내밀고 팔을 흔들며 펄쩍 뛰는 초록 세균 …】(L13c 날 항원)과 가른다 — 혀를 내밀지 않고 깃대투성이.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('하늘색 Y자 집게', f'★ {B} 성 세계(s13)의 항체도 Y — 황토 깃발이 Y 자이고 작은 것은 팔 끝이 안으로 굽은 집게(【Y 자 황토 깃발 — …】) · 빛깔(황토)과 깃발 천으로 이쪽(하늘색 집게)과 가른다.')
add('지팡이', f'★ {B} L13f s4 · s5 IgG 연대 깃발의 지팡이 손잡이 = G(「지」) — 옛 s13p01#1 의 지팡이를 이었다.')
add('불붙은 성냥', f'★ {B} L13f s6 뚱보 경비(비만세포)가 꽃가루 공이 두 IgE 를 잇는 순간 치켜든 성냥 한 움큼이 확.')
add('배 불룩한 뚱보 흰 옷 경비(눈 질끈 · 손바닥 펴 세균을 막음 · 불붙은 성냥 한 움큼)', f'★ {B} L13f s6 — 배 왼쪽에 거꾸로 박힌 집게 Y 셋(IgE 가 Fc 로 붙음) · 두 집게가 꽃가루 공을 함께 물자 성냥이 확(교차결합 → 히스타민).')
add('돌로 두른 도랑 끝을 막은 나무 판자 보(洑) + 넘쳐 고인 물', f'★ {B} L13f s9 — IgM 의 별 바퀴가 보를 들이받아 물이 터짐 = 항체가 켜는 고전경로(L13a 의 경비가 보를 듦과 짝).')
add('몸 가운데 둥근 구멍이 뚫리고 그 구멍으로 물줄기가 지나가는 초록 세균(구멍 둘레가 쭈글쭈글)', f'★ {B} L13f s9 별 바퀴 끝에 몰린 세균 하나의 배 구멍 — 고전경로가 끝내 낸 MAC.')
add('망토 두른 사람 + 품에 안은 흰 종이 두루마리', f'★ {B} L13f s11 — 두루마리를 등에 멘 망토의 두 손을 집게 Y 가 빼곡히 물어 오두막(세포) 창틀을 못 잡음 = 중화.')
add('장난감 벌(노란 벌)', f'★ {B} 출정한 다섯 연대 — 큰 Y 를 든 넷(중쇄 · 경쇄) · 지팡이 깃발 무리(G) · 별 바퀴를 미는 벌(M) · A 사다리 위 쌍둥이(A) · 갈퀴 벌(E) · 하품하는 D 명찰 벌(D). 배지는 몸통 옆(이 과의 벌은 L13e 보다 커서 배지 반지름 8 ~ 11.5).')
add('두 팔을 위로 벌려 몸이 Y 자가 된 쌍둥이 둘', f'⚠ {B} L13f s10 A 자 사다리 위 쌍둥이 벌의 Y 이음 깃발(IgA 이량체)과 가른다 — 그쪽은 벌이 깃발을 든다.')
add('분홍 천막(엄마 배) 속 아기 집', f'⚠ {B} L13f s5 유리 공 배의 임신부(IgG 태반 통과)와 가른다.')
add('작은 흰 덩이(큰 흰 덩이처럼 둥근 흰 몸 · 몸집이 작다)', f'★ {B} L13f s12 큰 흰 덩이가 집게 Y 투성이 세균을 깃대째 쥐고 삼킴 = 항체의 옵소닌화(L13b 의 보체 옵소닌화와 같은 일).')
G['J'] = f'J자로 굽은 작은 쇠고리 (J 사슬 — L13f s10 Y 둘을 깃대 끝끼리 이은 IgA 이량체의 고리) {B}. ⚠ C 자 갈고리(PKC · 비타민 C · CCA)와 가른다 — J 는 긴 곧은 대 끝이 굽는다.'
G['A'] += f' ★ {B} 일곱째 — IgA(L13f s10 쌍둥이 벌이 딛고 선 펼친 접이 사다리 · 샘가).'
G['D'] += f' ★ {B} IgD — L13f s3 하품하는 벌 가슴의 흰 D 자 명찰(옛 s13p01#4).'
G['E'] += f' ★ {B} IgE — L13f s7 세 갈래 갈퀴(가로대 셋 = 날 셋 · 옛 s13p01#3).'
G['M'] += f' ★ {B} IgM — L13f s8 별 바퀴 한가운데 두 봉우리 검은 쇠 장식(옛 s13p01#0 · 왕관 금지).'
out = json.dumps(d, ensure_ascii=False, indent=1)
assert json.loads(out) == d
open(P, 'w', encoding='utf-8').write(out)
print('예약', len(R), '· 글자', len(G))
